/**
 * Exercise private recording uploads on an explicitly authorized deployment.
 * Uses synthetic archives generated by scripts/make-acquisition-fixture.py.
 * One transfer is interrupted after a real acknowledged chunk; no backend
 * states, import results or file bodies are fabricated. Two QA accounts and one
 * ready acquisition remain for an operator's backup/restore check. Credentials
 * stay in memory; exact cleanup identities are recorded in the report.
 */
import assert from 'node:assert/strict';
import { createHash, randomBytes, randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';

const [baseArgument, outputArgument, archiveArgument, corruptArgument, ...extra] = process.argv.slice(2);
if (!baseArgument || !outputArgument || !archiveArgument || !corruptArgument || extra.length) {
  throw new Error('Usage: node web/scripts/check-workspace-acquisitions-browser.mjs WORKSPACE_URL OUTPUT_DIRECTORY VALID_ZIP CORRUPT_ZIP');
}
const address = new URL(baseArgument);
if (!['http:', 'https:'].includes(address.protocol) || address.username || address.password || address.search || address.hash) {
  throw new Error('Use an explicit HTTP(S) workspace URL without credentials, query or fragment.');
}
const base = address.href;
const output = resolve(outputArgument) + sep;
const archivePath = resolve(archiveArgument), corruptPath = resolve(corruptArgument);
const archiveBytes = await readFile(archivePath);
assert.ok(archiveBytes.length > 4 * 1024 * 1024 && archiveBytes.length < 32 * 1024 * 1024, 'Use the bounded synthetic transfer fixture.');
const hash = value => createHash('sha256').update(value).digest('hex');
const archiveHash = hash(archiveBytes);
const timeout = Number(process.env.MERIDIAN_IMPORT_QA_TIMEOUT_MS || 300_000);
if (!Number.isSafeInteger(timeout) || timeout < 30_000 || timeout > 1_800_000) throw new Error('Invalid MERIDIAN_IMPORT_QA_TIMEOUT_MS.');
await mkdir(output, { recursive: true });
const wrong = Buffer.from(archiveBytes);
wrong[200] ^= 1;
const wrongPath = `${output}wrong-prefix.zip`;
await writeFile(wrongPath, wrong);
const moduleUrl = process.env.MERIDIAN_PLAYWRIGHT_MODULE ? pathToFileURL(resolve(process.env.MERIDIAN_PLAYWRIGHT_MODULE)).href
  : new URL('../../build/browser-tools/node_modules/playwright/index.mjs', import.meta.url).href;
const { chromium } = await import(moduleUrl);
const browser = await chromium.launch({ headless: true, ...(process.env.MERIDIAN_BROWSER_EXECUTABLE ? { executablePath: process.env.MERIDIAN_BROWSER_EXECUTABLE } : {}) });
const context = await browser.newContext({ viewport: { width: 1440, height: 1100 }, acceptDownloads: true });
const other = await browser.newContext();
const page = await context.newPage(), peer = await other.newPage();
const stamp = `${Date.now().toString(36)}-${randomBytes(3).toString('hex')}`;
const usernames = [`qa-input-${stamp}`, `qa-input-peer-${stamp}`];
const password = `Qa!${randomBytes(24).toString('base64url')}`;
const accounts = [], acquisitionIds = [], deletedIds = [], checks = [], errors = [], cspErrors = [];
const observedStates = new Set();
const uploads = [];
let projectId, retainedId, deletedReadyId, failure, contentSecurityPolicy;
const check = (label, condition) => { assert.ok(condition, label); checks.push(label); };
const collection = () => `/projects/${projectId}/acquisitions`;
const acquisitionUrl = id => `${base}#project/${projectId}/data/acquisitions/${id}`;
for (const target of [page, peer]) {
  target.on('pageerror', error => errors.push(error.message));
  target.on('console', message => {
    if (message.type() === 'error' && /content security policy|violat.*(?:directive|policy)|refused to (?:load|execute|apply|connect)/i.test(message.text())) cspErrors.push(message.text());
  });
}
page.on('request', request => {
  if (request.method() === 'PUT' && new URL(request.url()).pathname.endsWith('/content')) {
    uploads.push({ acquisition_id: new URL(request.url()).pathname.split('/').at(-2), offset: Number(request.headers()['upload-offset']) });
  }
});
page.on('response', async response => {
  if (!response.ok() || !new URL(response.url()).pathname.includes('/acquisitions')) return;
  try { const value = await response.json(); if (value.acquisition?.state) observedStates.add(value.acquisition.state); } catch { /* Downloads and interrupted responses are not JSON observations. */ }
});
async function progress(state) {
  await writeFile(`${output}progress.json`, JSON.stringify({ state, checked_at: new Date().toISOString(),
    accounts, project_id: projectId, acquisition_ids: acquisitionIds, retained_acquisition_id: retainedId,
    checks: checks.length }, null, 2) + '\n');
  console.log(state);
}
async function api(target, path, method = 'GET', body) {
  return target.evaluate(async ({ path, method, body }) => {
    const session = await (await fetch('/api/v1/session', { cache: 'no-store' })).json();
    const response = await fetch(`/api/v1${path}`, { method, cache: 'no-store',
      headers: { 'Content-Type': 'application/json', 'X-CSRFToken': session.csrf_token },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
    const text = await response.text();
    let payload = null;
    try { payload = JSON.parse(text); } catch { /* Denied files should be JSON, never retain unexpected binary here. */ }
    return { status: response.status, payload, headers: Object.fromEntries(response.headers) };
  }, { path, method, body });
}
async function register(target, username) {
  await target.goto(base);
  await target.getByRole('button', { name: 'Create account', exact: true }).click();
  await target.getByLabel('Username', { exact: true }).fill(username);
  await target.getByLabel('Password', { exact: true }).fill(password);
  const [response] = await Promise.all([
    target.waitForResponse(item => new URL(item.url()).pathname === '/api/v1/auth/register' && item.request().method() === 'POST'),
    target.getByRole('button', { name: 'Create account', exact: true }).click(),
  ]);
  if (response.ok()) accounts.push(username);
  await target.getByRole('heading', { name: 'Projects', exact: true }).waitFor();
}
async function open(id) {
  await page.goto(acquisitionUrl(id));
  await page.locator('.acquisition-detail').waitFor();
}
async function startUpload(name, filename) {
  await page.goto(`${base}#project/${projectId}/data`);
  await page.getByRole('button', { name: 'Upload recording', exact: true }).click();
  await page.getByLabel('Acquisition name', { exact: true }).fill(name);
  await page.getByLabel('Recording archive', { exact: true }).setInputFiles(filename);
  const [created] = await Promise.all([
    page.waitForResponse(item => new URL(item.url()).pathname === `/api/v1${collection()}` && item.request().method() === 'POST'),
    page.getByRole('button', { name: 'Start upload', exact: true }).click(),
  ]);
  const value = await created.json();
  assert.equal(created.status(), 201, JSON.stringify(value));
  acquisitionIds.push(value.acquisition.id);
  return value.acquisition.id;
}
async function state(label) {
  await page.locator('.acquisition-detail .acquisition-status').filter({ hasText: new RegExp(`^${label}$`) }).waitFor({ timeout });
}
async function download(label, filename) {
  const pending = page.waitForEvent('download');
  await page.getByRole(label === 'Download original archive' ? 'link' : 'button', { name: label, exact: true }).click();
  const value = await pending;
  await value.saveAs(`${output}${filename}`);
  return readFile(`${output}${filename}`);
}
try {
  const response = await page.goto(base);
  contentSecurityPolicy = await response.headerValue('content-security-policy');
  await register(page, usernames[0]);
  await page.getByRole('button', { name: /New project/ }).click();
  await page.getByLabel('Project name', { exact: true }).fill('Private sensor import acceptance');
  await page.getByRole('button', { name: 'Create project', exact: true }).click();
  await page.getByRole('heading', { name: 'Acquisitions', exact: true }).waitFor();
  projectId = new URL(page.url()).hash.split('/')[1];
  const list = await api(page, collection());
  check('the deployment explicitly enables recording uploads', list.payload.service.enabled === true);
  check('the browser displays actual transfer and preparation limits', (await page.locator('.acquisition-limits').textContent()).includes('GiB'));
  await progress('INTERRUPTING_UPLOAD');

  let interrupted;
  const interruptedRequest = new Promise(resolve => { interrupted = resolve; });
  const interrupt = async route => {
    if (route.request().method() === 'PUT' && route.request().headers()['upload-offset'] === String(4 * 1024 * 1024)) {
      await route.abort('failed');
      interrupted();
    } else await route.continue();
  };
  await page.route('**/acquisitions/*/content', interrupt);
  retainedId = await startUpload('Synthetic stereo recording', archivePath);
  let interruptTimer;
  try {
    await Promise.race([interruptedRequest, new Promise((_, reject) => {
      interruptTimer = setTimeout(() => reject(new Error('The transfer did not reach its second chunk.')), 60_000);
    })]);
  } finally { clearTimeout(interruptTimer); }
  const partial = (await api(page, `${collection()}/${retainedId}`)).payload.acquisition;
  check('one real acknowledged chunk survives an interrupted connection', partial.state === 'receiving' && partial.bytes_received === 4 * 1024 * 1024);
  await page.unroute('**/acquisitions/*/content', interrupt);
  await page.reload();
  await page.getByRole('heading', { name: 'Acquisitions', exact: true }).waitFor();
  await page.locator('.acquisition-row').filter({ hasText: 'Synthetic stereo recording' }).click();
  await page.getByRole('button', { name: 'Resume upload', exact: true }).waitFor();
  check('refresh restores the durable acquisition and acknowledged byte count', (await page.locator('.acquisition-progress').textContent()).includes('4.0 MiB'));
  const uploadsBeforeMismatch = uploads.length;
  await page.getByLabel('Archive to resume', { exact: true }).setInputFiles(wrongPath);
  await page.getByRole('button', { name: 'Resume upload', exact: true }).click();
  await page.getByText('This archive differs from the received bytes.', { exact: false }).waitFor();
  check('a same-size mismatching archive cannot send any suffix', uploads.length === uploadsBeforeMismatch
    && (await api(page, `${collection()}/${retainedId}`)).payload.acquisition.bytes_received === partial.bytes_received);
  await page.getByLabel('Archive to resume', { exact: true }).setInputFiles(archivePath);
  await page.getByRole('button', { name: 'Resume upload', exact: true }).click();
  await state('Ready to inspect');
  const ready = (await api(page, `${collection()}/${retainedId}`)).payload.acquisition;
  check('the completed source has its independently expected full SHA-256', ready.sha256 === archiveHash && ready.size_bytes === archiveBytes.length);
  check('accepted metadata does not claim physical or VIO readiness', await page.getByText('Calibration validity and estimator readiness have not been assessed.', { exact: false }).isVisible()
    && await page.getByRole('button', { name: /^Run/ }).count() === 0);
  check('a resumed transfer sends only the previously missing chunk', uploads.filter(value => value.acquisition_id === retainedId && value.offset === 0).length === 1);
  const original = await download('Download original archive', 'original.zip');
  check('the owned original download preserves every source byte', hash(original) === archiveHash);
  const descriptor = JSON.parse(await download('Download descriptor', 'acquisition.json'));
  check('the descriptor download contains the actual acquisition contract', descriptor.kind === 'acquisition' && descriptor.schema_version === 1 && descriptor.streams.length === 3);
  check('the no-reference acquisition retains explicit unavailable evaluation reference', await page.getByText('Not included', { exact: true }).isVisible());
  await page.screenshot({ path: `${output}ready-dark.png`, fullPage: true });
  await page.getByLabel('Appearance', { exact: true }).selectOption('light');
  await page.screenshot({ path: `${output}ready-light.png`, fullPage: true });
  await page.setViewportSize({ width: 390, height: 844 });
  check('acquisition detail has no horizontal overflow on a narrow screen', await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth));
  await page.screenshot({ path: `${output}ready-mobile.png`, fullPage: true });
  await page.setViewportSize({ width: 1440, height: 1100 });
  await progress('CHECKING_OWNER_BOUNDARIES');

  await peer.goto(base);
  check('an unauthenticated client cannot download the original', (await api(peer, `${collection()}/${retainedId}/original`)).status === 401);
  await register(peer, usernames[1]);
  for (const suffix of ['', '/chunks', '/descriptor', '/report', '/original']) {
    check(`another account cannot read acquisition ${suffix || 'metadata'}`, (await api(peer, `${collection()}/${retainedId}${suffix}`)).status === 404);
  }
  check('another account cannot cancel or delete the acquisition',
    (await api(peer, `${collection()}/${retainedId}/cancel`, 'POST', { schema_version: 1 })).status === 404
    && (await api(peer, `${collection()}/${retainedId}`, 'DELETE')).status === 404);
  await peer.goto(acquisitionUrl(retainedId));
  await peer.getByRole('heading', { name: 'Acquisition unavailable', exact: true }).waitFor();
  check('a foreign deep link exposes no acquisition metadata or download controls', await peer.locator('.acquisition-detail').count() === 0);

  await progress('CHECKING_REJECTION_AND_CANCELLATION');
  const rejectedId = await startUpload('Deliberately corrupt fixture', corruptPath);
  await state('Rejected');
  const rejected = (await api(page, `${collection()}/${rejectedId}`)).payload.acquisition;
  check('a corrupt archive becomes durably rejected with an actionable failure', Boolean(rejected.failure?.code) && rejected.files_available === false);
  await page.reload();
  await state('Rejected');
  check('rejection survives refresh without exposing download controls', await page.getByRole('link', { name: 'Download original archive', exact: true }).count() === 0);
  const created = await api(page, collection(), 'POST', { schema_version: 1, name: 'Cancelled transfer',
    filename: 'cancelled.zip', size_bytes: archiveBytes.length, idempotency_key: randomUUID() });
  assert.equal(created.status, 201, JSON.stringify(created));
  const cancelledId = created.payload.acquisition.id;
  acquisitionIds.push(cancelledId);
  await open(cancelledId);
  await page.getByRole('button', { name: 'Cancel acquisition', exact: true }).click();
  await page.getByRole('button', { name: 'Keep acquisition', exact: true }).click();
  check('cancelling the confirmation preserves the receiving acquisition', (await api(page, `${collection()}/${cancelledId}`)).payload.acquisition.state === 'receiving');
  await page.getByRole('button', { name: 'Cancel acquisition', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Cancel acquisition', exact: true }).click();
  await state('Cancelled');
  check('confirmed cancellation persists and releases the upload', (await api(page, `${collection()}/${cancelledId}`)).payload.acquisition.reserved_bytes === 0);
  await page.getByRole('button', { name: 'Delete acquisition', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Delete acquisition', exact: true }).click();
  await page.getByRole('heading', { name: 'Acquisitions', exact: true }).waitFor();
  deletedIds.push(cancelledId);

  await progress('CHECKING_SOURCE_DELETION');
  deletedReadyId = await startUpload('Disposable ready fixture', archivePath);
  await state('Ready to inspect');
  const saved = await download('Download original archive', 'deleted-original.zip');
  await page.getByRole('button', { name: 'Delete acquisition', exact: true }).click();
  await page.getByRole('button', { name: 'Keep acquisition', exact: true }).click();
  check('cancelling deletion preserves source availability', (await api(page, `${collection()}/${deletedReadyId}`)).payload.acquisition.files_available);
  await page.getByRole('button', { name: 'Delete acquisition', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Delete acquisition', exact: true }).click();
  await page.getByRole('heading', { name: 'Acquisitions', exact: true }).waitFor();
  deletedIds.push(deletedReadyId);
  const deleted = (await api(page, `${collection()}/${deletedReadyId}`)).payload.acquisition;
  check('deletion retains an explicitly unavailable metadata version', deleted.availability === 'deleted' && deleted.files_available === false);
  check('deleted originals cannot be downloaded again', (await api(page, `${collection()}/${deletedReadyId}/original`)).status === 410);
  check('a previously downloaded archive remains intact after deletion', hash(saved) === archiveHash && hash(await readFile(`${output}deleted-original.zip`)) === archiveHash);
  await open(deletedReadyId);
  await state('Deleted');
  check('deleted acquisition UI does not offer download or repeat deletion', await page.locator('.acquisition-downloads').count() === 0 && await page.getByRole('button', { name: 'Delete acquisition', exact: true }).count() === 0);
  await open(retainedId);
  check('the separate ready acquisition remains available for restoration checks', (await api(page, `${collection()}/${retainedId}`)).payload.acquisition.files_available);
  await page.getByRole('button', { name: 'Sign out', exact: true }).click();
  await page.getByRole('heading', { name: 'Sign in', exact: true }).waitFor();
  check('logout removes private acquisition content and revokes subsequent reads', await page.locator('.acquisitions').count() === 0
    && (await api(page, `${collection()}/${retainedId}`)).status === 401);
  check('all durable lifecycle outcomes were observed from actual API responses', ['receiving', 'validating', 'ready', 'rejected', 'cancelled'].every(value => observedStates.has(value)));
  check('no uncaught browser or Content-Security-Policy errors occurred', errors.length === 0 && cspErrors.length === 0);
} catch (error) {
  failure = String(error.stack || error).replaceAll(password, '[redacted]');
  process.exitCode = 1;
  try { await page.screenshot({ path: `${output}failure.png`, fullPage: true }); } catch { /* Preserve the original failure. */ }
} finally {
  const report = { schema_version: 1, base, checked_at: new Date().toISOString(), passed: !failure,
    environment_description: process.env.MERIDIAN_QA_ENVIRONMENT || 'Not specified by the operator.',
    created_accounts: accounts, project_id: projectId, created_acquisition_ids: acquisitionIds,
    retained_acquisition_id: retainedId, deleted_acquisition_ids: deletedIds, deleted_ready_acquisition_id: deletedReadyId,
    source_sha256: archiveHash, source_size_bytes: archiveBytes.length, source_synthetic: true,
    observed_states: [...observedStates].sort(), upload_requests: uploads,
    content_security_policy: contentSecurityPolicy, checks, errors, cspErrors, ...(failure ? { failure } : {}),
    limitations: [
      'The archives contain synthetic convention fixtures and transfer padding, not a new physical acquisition.',
      'No estimator, calibration fit, sensor-quality investigation or flight validation is executed.',
      'The transfer is deliberately interrupted by browser request routing after one actual acknowledged chunk.',
      'The retained ready acquisition and two QA accounts require a separate backup/restore proof and exact operator cleanup.',
      'Credentials and cookies are not saved; an operator can identify retained data from the recorded IDs.',
    ] };
  await writeFile(`${output}report.json`, JSON.stringify(report, null, 2) + '\n');
  await progress(failure ? 'FAILED' : 'PASSED');
  console.log(JSON.stringify({ passed: !failure, checks: checks.length, accounts, projectId, retainedId, output,
    ...(failure ? { failure } : {}) }, null, 2));
  await browser.close();
}
